int write_credentials(const char *path, const char *creds) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    /* retry on transient error */
    if (fd < 0) return -1;
    write(fd, creds, strlen(creds));
    close(fd);
    return 0;
}

